{"filePath":"/home/runner/opencode-agentic-engine/src/core/llm.ts","oldString":"  /**
   * Resolve model for a given tool name using 3-level fallback:
   *   1. Per-tool override (sessionStore.getToolPreference)
   *   2. Category by complexity tier (sessionStore.getCategoryPreference)
   *   3. Engine config default
   */
  private resolveModelForTool(toolName?: string): { providerID: string; modelID: string } | undefined {
    if (!toolName || !this.sessionStore || !this.pluginSessionId) {
      return this.parseModelForSDK()
    }

    // Priority 1: per-tool override
    const toolModel = this.sessionStore.getToolPreference(this.pluginSessionId, toolName)
    if (toolModel) {
      return this.parseModelForSDK(toolModel)
    }

    // Priority 2: category by complexity tier
    const category = TOOL_COMPLEXITY[toolName]
    if (category) {
      const catModel = this.sessionStore.getCategoryPreference(this.pluginSessionId, category)
      if (catModel) {
        return this.parseModelForSDK(catModel)
      }
    }

    // Priority 3: engine default
    return this.parseModelForSDK()
  }

